package com.logiplatform.service;
import com.logiplatform.dto.OperationsDtos.FleetLiveResponse; import com.logiplatform.model.*; import com.logiplatform.repository.*; import com.logiplatform.tenancy.TenantContext; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class FleetControlService { private final VehicleRepository vehicles; private final DriverRepository drivers; private final TripRepository trips; private final VehicleGpsPositionRepository gps; public FleetControlService(VehicleRepository v,DriverRepository d,TripRepository t,VehicleGpsPositionRepository g){vehicles=v;drivers=d;trips=t;gps=g;}
 @Transactional(readOnly=true) public List<FleetLiveResponse> live(){UUID t=TenantContext.getTenantId();List<FleetLiveResponse> out=new ArrayList<>();for(Vehicle v:vehicles.findAllByTenantId(t)){var pos=gps.findFirstByTenantIdAndVehicleIdOrderByRecordedAtDesc(t,v.getId()).orElse(null);var trip=trips.findAllByTenantIdAndScheduledDepartureGreaterThanEqualAndScheduledDepartureLessThanOrderByScheduledDepartureAsc(t,java.time.Instant.now().minusSeconds(86400),java.time.Instant.now().plusSeconds(86400*2)).stream().filter(x->x.getVehicleId().equals(v.getId())&&(x.getStatus()==TripStatus.IN_PROGRESS||x.getStatus()==TripStatus.PLANNED)).findFirst().orElse(null);String dn=trip==null?null:drivers.findByIdAndTenantId(trip.getDriverId(),t).map(Driver::getFullName).orElse(null);out.add(new FleetLiveResponse(v.getId(),v.getRegistrationNumber(),v.getStatus().name(),trip==null?null:trip.getDriverId(),dn,trip==null?null:trip.getId(),trip==null?null:trip.getStatus().name(),pos==null?null:pos.getLatitude(),pos==null?null:pos.getLongitude(),pos==null?null:pos.getSpeedKmh(),pos==null?null:pos.getRecordedAt()));}return out;}
}
